// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Draft history"
// Changes: Keyboard behaviour of a horizontal tab list (arrows wrap, Home/End; other keys are not ours).

import { describe, expect, it } from 'vitest'
import { tabKeyTarget } from './tabKeys'

describe('tabKeyTarget', () => {
  it('arrows move to the neighbouring tab and wrap around', () => {
    expect(tabKeyTarget('ArrowRight', 0, 3)).toBe(1)
    expect(tabKeyTarget('ArrowRight', 2, 3)).toBe(0)
    expect(tabKeyTarget('ArrowLeft', 0, 3)).toBe(2)
    expect(tabKeyTarget('ArrowLeft', 2, 3)).toBe(1)
  })

  it('Home and End go to the first and last tab', () => {
    expect(tabKeyTarget('Home', 2, 3)).toBe(0)
    expect(tabKeyTarget('End', 0, 3)).toBe(2)
  })

  it('other keys (and vertical arrows) are left to the browser', () => {
    expect(tabKeyTarget('ArrowDown', 0, 3)).toBeNull()
    expect(tabKeyTarget('Enter', 0, 3)).toBeNull()
    expect(tabKeyTarget('a', 0, 3)).toBeNull()
  })
})
